import {query} from '../client.js';
function required(value,name){if(!value||value===true)throw new Error('Provide --'+name);return value;}
function boolean(value,name){if(value===true||value==='true')return true;if(value===false||value==='false')return false;throw new Error('--'+name+' must be true or false');}
function ids(value){return String(required(value,'ids')).split(',').map(id=>id.trim()).filter(Boolean);}
async function list(client,path,filters,all){
  let result=await client.get(path+query(filters));
  if(!all)return result;
  const items=[...result.items],seen=new Set();
  while(result.nextCursor){
    if(seen.has(result.nextCursor))throw new Error('Server repeated a pagination cursor');
    seen.add(result.nextCursor);result=await client.get(path+query({...filters,cursor:result.nextCursor}));items.push(...result.items);
  }
  return {...result,items,nextCursor:null};
}
export async function feedCommand({args,options,client,print}) {
  const [action='list',type,target]=args;
  if(action==='watch'||action==='unwatch'){
    if(!['issue','project'].includes(type)||!target)throw new Error('Usage: crew feed '+action+' issue|project ID');
    return print(action==='watch'?await client.post('/subscriptions',{targetType:type,targetId:target}):await client.delete('/subscriptions/'+type+'/'+encodeURIComponent(target)));
  }
  const orgId=required(options.org,'org');
  if(action==='subscriptions')return print(await list(client,'/subscriptions',{orgId,projectId:options.project,limit:options.limit,cursor:options.cursor},options.all));
  if(action!=='list')throw new Error('Unknown feed action. Use crew feed --help');
  return print(await list(client,'/activity',{orgId,projectId:options.project,issueId:options.issue,userId:options.user,entityType:options.entity,action:options.action,from:options.from,to:options.to,limit:options.limit,cursor:options.cursor},options.all));
}
feedCommand.help=`crew feed list --org ID [--project ID] [--issue ID] [--user ACTOR] [--entity TYPE] [--action ACTION] [--from ISO] [--to ISO] [--limit N] [--cursor CURSOR] [--all]
crew feed subscriptions --org ID [--project ID] [--limit N] [--cursor CURSOR] [--all]
crew feed watch issue|project ID
crew feed unwatch issue|project ID
Watch actions apply only to your account. Unwatch mutes ordinary automatic subscriptions; explicit mentions still notify. --all traverses every accessible page.`;
export async function inboxCommand({args,options,client,print}) {
  const [action='list',id]=args;
  if(action==='read'||action==='unread'){
    if(!id)throw new Error('Usage: crew inbox '+action+' NOTIFICATION');
    return print(await client.patch('/notifications/'+encodeURIComponent(id),{read:action==='read'}));
  }
  const orgId=required(options.org,'org');
  if(action==='list')return print(await list(client,'/notifications',{orgId,projectId:options.project,state:options.state,limit:options.limit,cursor:options.cursor},options.all));
  if(action==='mark'||action==='mark-all'){
    const read=options.read===undefined?true:boolean(options.read,'read');
    if(action==='mark-all'&&!options.yes)throw new Error('Marking every accessible notification requires --yes');
    return print(await client.post('/notifications/mark',{orgId,read,...(action==='mark-all'?{all:true}:{ids:ids(options.ids)})}));
  }
  if(action==='preferences'){
    const body={orgId};
    if(options.email!==undefined)body.emailEnabled=boolean(options.email,'email');
    if(options['mentions-only']!==undefined)body.mentionsOnly=boolean(options['mentions-only'],'mentions-only');
    return print(Object.keys(body).length>1?await client.patch('/notification-preferences',body):await client.get('/notification-preferences'+query({orgId})));
  }
  if(action==='digest')return print(await client.post('/digests',{orgId}));
  if(action==='digests')return print(await list(client,'/digests',{orgId,limit:options.limit,cursor:options.cursor},options.all));
  throw new Error('Unknown inbox action. Use crew inbox --help');
}
inboxCommand.help=`crew inbox list --org ID [--project ID] [--state all|unread|read] [--limit N] [--cursor CURSOR] [--all]
crew inbox read|unread NOTIFICATION
crew inbox mark --org ID --ids ID,ID [--read true|false]
crew inbox mark-all --org ID --yes [--read true|false]
crew inbox preferences --org ID [--email true|false] [--mentions-only true|false]
crew inbox digest --org ID
crew inbox digests --org ID [--limit N] [--cursor CURSOR] [--all]
Digests batch up to 200 newly unread visible notifications once into the shared local outbox. The count/remaining fields let you deliberately request a further batch.`;

import {insightSearchCommands} from './insight-search.js';
import {feedCommand,inboxCommand} from './insight-activity.js';
export const commands={...insightSearchCommands,feed:feedCommand,inbox:inboxCommand};

import {useState} from 'preact/hooks';
import {Page,Field,Button,Notice,Empty,Loading,useLoad} from '../../components/ui.jsx';
import {queryString} from '../../api.js';
import {useLiveUpdates} from '../../live.js';
import {LiveControl,ActivityEntry} from './activity.jsx';
import {notificationPath} from './activity-state.js';
function ErrorDetails({error}) {
  if(!error?.details)return null;
  return <ul className="field-errors">{Object.entries(error.details).map(([key,message])=><li key={key}>{key}: {String(message)}</li>)}</ul>;
}
export function WatchPanel({api,orgId}) {
  const [type,setType]=useState('issue'),[targetId,setTargetId]=useState('');
  const [cursor,setCursor]=useState(''),[history,setHistory]=useState([]);
  const [error,setError]=useState(null),[busy,setBusy]=useState(false);
  const load=useLoad(()=>api.get('/subscriptions?'+queryString({orgId,cursor,limit:20})),[orgId,cursor]);
  async function watch(event){
    event.preventDefault();setBusy(true);setError(null);
    try{await api.post('/subscriptions',{targetType:type,targetId:targetId.trim()});setTargetId('');setCursor('');setHistory([]);load.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  async function unwatch(item){
    setBusy(true);setError(null);
    try{await api.delete('/subscriptions/'+item.targetType+'/'+encodeURIComponent(item.targetId));load.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  return <section><h2>Watching</h2><p>Creators, assignees and mentioned people follow an issue automatically. Muting an issue stops ordinary watcher updates; direct mentions remain visible.</p>
    <form className="insight-filters" onSubmit={watch}><Field label="Watch"><select value={type} onChange={event=>setType(event.currentTarget.value)}><option value="issue">Issue</option><option value="project">Project</option></select></Field>
      <Field label={type==='issue'?'Issue ID':'Project ID'} required value={targetId} onInput={event=>setTargetId(event.currentTarget.value)}/><Button busy={busy} type="submit">Watch</Button></form>
    <Notice error={error??load.error}/><ErrorDetails error={error}/>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No watches in this organization.</Empty>:<ul>{load.data.items.map(item=><li key={item.id}>
      <a href={'#/'+(item.targetType==='issue'?'issues/':'projects/')+encodeURIComponent(item.targetId)}>{item.targetType}: {item.targetId}</a> · {item.manual?'manually watched':item.reason}
      <Button busy={busy} onClick={()=>unwatch(item)}>Mute</Button></li>)}</ul>}
    <div className="pagination"><Button disabled={!history.length} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));}}>Previous watches</Button>
      <Button disabled={!load.data?.nextCursor} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);}}>Next watches</Button></div>
  </section>;
}
function DigestPanel({api,orgId}) {
  const [cursor,setCursor]=useState(''),[history,setHistory]=useState([]),[busy,setBusy]=useState(false),[error,setError]=useState(null),[message,setMessage]=useState('');
  const load=useLoad(()=>api.get('/digests?'+queryString({orgId,cursor,limit:10})),[orgId,cursor]);
  async function batch(){
    setBusy(true);setError(null);setMessage('');
    try{const result=await api.post('/digests',{orgId});setMessage(result.count?'Queued '+result.count+' updates in your email outbox. '+result.remaining+' remain.':'No new unread updates need a digest.');load.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  return <section><h2>Email digests</h2><p>Queue a batch of up to 200 new unread updates in your private local email outbox. This does not mark the inbox read.</p>
    <Button busy={busy} onClick={batch}>Queue unread digest</Button><Notice error={error??load.error}/><Notice>{message}</Notice>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No digests queued yet.</Empty>:load.data.items.map(digest=><details key={digest.id}><summary>{new Date(digest.createdAt).toLocaleString()} · {digest.count} accessible updates</summary><pre>{digest.textBody||'These updates are no longer accessible.'}</pre></details>)}
    <div className="pagination"><Button disabled={!history.length} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));}}>Previous digests</Button><Button disabled={!load.data?.nextCursor} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);}}>Next digests</Button></div>
  </section>;
}
function Preferences({api,orgId}) {
  const load=useLoad(()=>api.get('/notification-preferences?'+queryString({orgId})),[orgId]);
  const [error,setError]=useState(null),[busy,setBusy]=useState(false);
  async function update(key,value){setBusy(true);setError(null);try{await api.patch('/notification-preferences',{orgId,[key]:value});load.reload();}catch(failure){setError(failure);}finally{setBusy(false);}}
  return <section><h2>Notification preferences</h2><Notice error={error??load.error}/>{load.loading?<Loading/>:load.data&&<div>
    <label><input type="checkbox" disabled={busy} checked={load.data.preferences.mentionsOnly} onChange={event=>update('mentionsOnly',event.currentTarget.checked)}/> Notify me only for explicit mentions</label>
    <label><input type="checkbox" disabled={busy} checked={load.data.preferences.emailEnabled} onChange={event=>update('emailEnabled',event.currentTarget.checked)}/> Enable email digest batching</label>
  </div>}</section>;
}
export function InboxPage({api,query,navigate}) {
  const [orgId,setOrgId]=useState(query.orgId??''),[state,setState]=useState('all'),[projectId,setProjectId]=useState('');
  const [cursor,setCursor]=useState(''),[history,setHistory]=useState([]),[selected,setSelected]=useState(new Set());
  const [error,setError]=useState(null),[busy,setBusy]=useState(false);
  const organizations=useLoad(()=>api.get('/orgs?limit=200'),[]);
  const load=useLoad(()=>orgId?api.get('/notifications?'+queryString({orgId,state,projectId,cursor,limit:25})):Promise.resolve(null),[orgId,state,projectId,cursor]);
  const live=useLiveUpdates({orgId,projectId,enabled:Boolean(orgId),onActivity:()=>load.reload()});
  function reset(){setCursor('');setHistory([]);setSelected(new Set());}
  async function mark(read,ids,all=false){
    setBusy(true);setError(null);
    try{await api.post('/notifications/mark',{orgId,read,...(all?{all:true}:{ids})});setSelected(new Set());load.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  async function markOne(item){
    setBusy(true);setError(null);
    try{await api.patch('/notifications/'+encodeURIComponent(item.id),{read:!item.read});load.reload();}
    catch(failure){setError(failure);}finally{setBusy(false);}
  }
  return <Page title="Inbox"><form className="insight-filters" onSubmit={event=>{event.preventDefault();reset();load.reload();navigate('/inbox?'+queryString({orgId}));}}>
    <Field label="Organization"><select value={orgId} onChange={event=>{setOrgId(event.currentTarget.value);reset();}}><option value="">Choose organization</option>{organizations.data?.items.map(org=><option value={org.id} key={org.id}>{org.name}</option>)}</select></Field>
    <Field label="State"><select value={state} onChange={event=>{setState(event.currentTarget.value);reset();}}><option value="all">All</option><option value="unread">Unread</option><option value="read">Read</option></select></Field>
    <Field label="Project ID" value={projectId} onInput={event=>{setProjectId(event.currentTarget.value);reset();}}/><Button type="submit">Refresh inbox</Button>
  </form><Notice error={error??load.error??organizations.error}/><ErrorDetails error={error}/>
  {orgId?<><LiveControl live={live}/><p role="status">{load.data?.unread??0} unread updates</p>
    <div className="insight-actions"><Button busy={busy} disabled={!selected.size} onClick={()=>mark(true,[...selected])}>Mark selected read</Button><Button busy={busy} disabled={!selected.size} onClick={()=>mark(false,[...selected])}>Mark selected unread</Button>
      <Button busy={busy} disabled={!load.data?.unread} onClick={()=>mark(true,null,true)}>Mark all read in this organization</Button></div>
    {load.loading?<Loading/>:!load.data?.items.length?<Empty>No {state==='all'?'':state+' '}updates match this inbox. Follow issues or projects to receive activity.</Empty>:load.data.items.map(item=><article key={item.id} data-testid={'notification-'+item.id} className={'notification-row '+(item.read?'read':'unread')}>
      <label><input aria-label={'Select notification '+item.id} type="checkbox" checked={selected.has(item.id)} onChange={event=>{const next=new Set(selected);event.currentTarget.checked?next.add(item.id):next.delete(item.id);setSelected(next);}}/></label>
      <div className="content"><a href={'#'+notificationPath(item)}>Open {item.activity.entityType}</a> · {item.reason}<ActivityEntry event={item.activity}/></div>
      <Button busy={busy} onClick={()=>markOne(item)}>{item.read?'Mark unread':'Mark read'}</Button>
    </article>)}
    <div className="pagination"><Button disabled={!history.length||load.loading} onClick={()=>{setCursor(history.at(-1));setHistory(history.slice(0,-1));setSelected(new Set());}}>Previous</Button>
      <Button disabled={!load.data?.nextCursor||load.loading} onClick={()=>{setHistory([...history,cursor]);setCursor(load.data.nextCursor);setSelected(new Set());}}>Next</Button></div>
    <details><summary>Watches, preferences and email digests</summary><Preferences api={api} orgId={orgId}/><WatchPanel api={api} orgId={orgId}/><DigestPanel api={api} orgId={orgId}/></details>
  </>:<Empty>Choose an organization to open your personal inbox.</Empty>}</Page>;
}

